text:
Looking at this, I'll build a self-contained `app.html` with a custom deterministic 2D-canvas coin renderer (full control over pixels for the grading harness), procedural metallic textures, a raking specular highlight, a reeded edge, and 4 procedurally-rendered edition tiles.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>WastedToken Mint — Collectible Physical Challenge Coins</title>
<style>
  :root{
    --bg:#0a0b0f; --panel:#14151b; --panel2:#1b1d25; --ink:#e9e6dd;
    --muted:#9a978d; --gold:#d8b46a; --gold2:#f0d79a; --line:#2a2c36;
    --serif:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,"Times New Roman",serif;
    --sans:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  }
  *{box-sizing:border-box}
  html,body{margin:0;padding:0}
  body{
    background:
      radial-gradient(1200px 700px at 50% -10%, #1a1c24 0%, rgba(26,28,36,0) 60%),
      linear-gradient(180deg,#0b0c11 0%, #08090d 100%);
    color:var(--ink); font-family:var(--sans); line-height:1.6;
    -webkit-font-smoothing:antialiased; overflow-x:hidden;
  }
  a{color:inherit;text-decoration:none}
  .wrap{max-width:1180px;margin:0 auto;padding:0 24px}

  /* ---------- Nav ---------- */
  header.nav{
    position:sticky;top:0;z-index:50;
    backdrop-filter:blur(10px);
    background:linear-gradient(180deg,rgba(8,9,13,.9),rgba(8,9,13,.55));
    border-bottom:1px solid var(--line);
  }
  .nav .wrap{display:flex;align-items:center;justify-content:space-between;height:66px}
  .brand{display:flex;align-items:center;gap:12px;font-family:var(--serif);letter-spacing:.06em}
  .brand .mark{
    width:30px;height:30px;border-radius:50%;
    background:conic-gradient(from 210deg,#8a6410,#f0d79a,#8a6410,#d4a52a,#8a6410);
    box-shadow:inset 0 0 0 2px #0a0b0f, 0 0 12px rgba(216,180,106,.35);
    display:grid;place-items:center;color:#2a1c05;font-weight:900;font-size:12px;
  }
  .brand b{font-weight:600;font-size:18px}
  .brand span{color:var(--gold)}
  .nav nav{display:flex;gap:26px;align-items:center;font-size:14px;color:var(--muted)}
  .nav nav a:hover{color:var(--ink)}
  .cart{
    display:inline-flex;align-items:center;gap:8px;border:1px solid var(--line);
    padding:7px 14px;border-radius:999px;color:var(--ink);font-size:13px;
    background:linear-gradient(180deg,#191b22,#111219);
  }
  .cart b{color:var(--gold);font-variant-numeric:tabular-nums}

  /* ---------- Hero ---------- */
  .hero{padding:56px 0 30px;text-align:center;position:relative}
  .eyebrow{
    color:var(--gold);letter-spacing:.42em;font-size:12px;text-transform:uppercase;
    margin-bottom:18px;
  }
  .hero h1{
    font-family:var(--serif);font-weight:600;letter-spacing:.01em;
    font-size:clamp(38px,7vw,78px);line-height:1.02;margin:0 0 10px;
    background:linear-gradient(180deg,#fbf6ea 0%, #d8b46a 60%, #9c7726 100%);
    -webkit-background-clip:text;background-clip:text;color:transparent;
    text-shadow:0 1px 0 rgba(0,0,0,.4);
  }
  .hero .sub{color:var(--muted);max-width:640px;margin:0 auto 8px;font-size:clamp(15px,2vw,18px)}
  .coin-stage{position:relative;margin:6px auto 0;width:min(92vw,600px)}
  #coin-hero{
    display:block;width:100%;height:auto;aspect-ratio:1/1;border-radius:50%;
    filter:drop-shadow(0 40px 60px rgba(0,0,0,.6));
  }
  .coin-cta{display:flex;gap:14px;justify-content:center;margin-top:14px;flex-wrap:wrap}
  .btn{
    cursor:pointer;font-family:var(--sans);font-size:14px;letter-spacing:.04em;
    padding:13px 26px;border-radius:999px;border:1px solid transparent;transition:.2s;
  }
  .btn.primary{
    color:#241a06;font-weight:700;
    background:linear-gradient(180deg,#f4dc9f,#cf9f42);
    box-shadow:0 8px 24px rgba(207,159,66,.28), inset 0 1px 0 rgba(255,255,255,.5);
  }
  .btn.primary:hover{transform:translateY(-1px);filter:brightness(1.05)}
  .btn.ghost{color:var(--ink);border-color:var(--line);background:#12131a}
  .btn.ghost:hover{border-color:var(--gold)}
  .specs{display:flex;gap:34px;justify-content:center;margin-top:34px;color:var(--muted);flex-wrap:wrap;font-size:13px}
  .specs b{display:block;color:var(--ink);font-family:var(--serif);font-size:20px;letter-spacing:.04em}

  /* ---------- Sections ---------- */
  section.block{padding:72px 0;border-top:1px solid var(--line)}
  .kicker{color:var(--gold);letter-spacing:.34em;font-size:12px;text-transform:uppercase;margin-bottom:14px}
  h2.title{font-family:var(--serif);font-weight:600;font-size:clamp(28px,4vw,44px);margin:0 0 18px}
  .about-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:48px;align-items:start}
  .about p{color:#c9c6bc;margin:0 0 16px}
  .pill-row{display:flex;flex-wrap:wrap;gap:10px;margin-top:20px}
  .pill{border:1px solid var(--line);border-radius:999px;padding:8px 15px;font-size:13px;color:var(--muted);background:#101119}
  .pill b{color:var(--gold)}
  .about aside{
    border:1px solid var(--line);border-radius:18px;padding:26px;
    background:linear-gradient(180deg,#14151d,#0e0f15);
  }
  .about aside h3{font-family:var(--serif);margin:0 0 6px;font-weight:600}
  .about aside ul{margin:14px 0 0;padding:0;list-style:none}
  .about aside li{display:flex;justify-content:space-between;padding:11px 0;border-top:1px dashed var(--line);color:#c9c6bc;font-size:14px}
  .about aside li span{color:var(--gold)}

  /* ---------- Collection ---------- */
  .grid{display:grid;grid-template-columns:repeat(4,1fr);gap:22px}
  .edition{
    position:relative;border:1px solid var(--line);border-radius:20px;overflow:hidden;
    background:linear-gradient(180deg,#15161e 0%, #0d0e14 100%);
    padding:22px 20px 24px;display:flex;flex-direction:column;transition:.25s;
  }
  .edition:hover{border-color:#3a3d49;transform:translateY(-4px);box-shadow:0 24px 40px rgba(0,0,0,.4)}
  .edition .canvas-holder{position:relative;width:100%;aspect-ratio:1/1}
  .edition-canvas{display:block;width:100%;height:100%;filter:drop-shadow(0 18px 26px rgba(0,0,0,.55))}
  .edition .row{display:flex;justify-content:space-between;align-items:baseline;margin-top:16px}
  .edition h3{font-family:var(--serif);font-weight:600;font-size:22px;margin:0}
  .edition .denom{color:var(--gold);font-size:13px;font-variant-numeric:tabular-nums}
  .edition p.desc{color:var(--muted);font-size:13px;margin:8px 0 16px;min-height:38px}
  .edition .foot{margin-top:auto;display:flex;align-items:center;justify-content:space-between;gap:10px}
  .price{font-family:var(--serif);font-size:18px}
  .buy{
    cursor:pointer;border:none;border-radius:999px;padding:10px 18px;font-size:13px;font-weight:700;
    letter-spacing:.03em;color:#241a06;
    background:linear-gradient(180deg,#f4dc9f,#cf9f42);
    box-shadow:inset 0 1px 0 rgba(255,255,255,.55), 0 6px 16px rgba(207,159,66,.25);
    transition:.18s;
  }
  .buy:hover{filter:brightness(1.06);transform:translateY(-1px)}
  .buy:active{transform:translateY(0)}
  .status{
    font-size:12px;letter-spacing:.12em;text-transform:uppercase;padding:9px 14px;border-radius:999px;
    border:1px solid var(--line);color:var(--muted);
  }
  .status.soldout{color:#e88a8a;border-color:#5a2b2b;background:rgba(90,43,43,.18)}
  .status.soon{color:#8ab6e8;border-color:#2b3f5a;background:rgba(43,63,90,.18)}
  .badge{
    position:absolute;top:16px;right:-40px;transform:rotate(45deg);
    padding:6px 46px;font-size:11px;letter-spacing:.18em;font-weight:800;color:#241a06;
    background:linear-gradient(180deg,#f0d79a,#cf9f42);box-shadow:0 4px 10px rgba(0,0,0,.4);
  }
  .badge.dark{background:linear-gradient(180deg,#4a4d57,#22242b);color:#cfd3dd}
  .edition[data-state="sold-out"] .canvas-holder{filter:saturate(.65) brightness(.86)}
  .edition[data-state="coming-soon"] .canvas-holder{filter:contrast(1.05)}

  footer{border-top:1px solid var(--line);padding:44px 0;color:var(--muted);font-size:13px}
  .foot-grid{display:flex;justify-content:space-between;gap:24px;flex-wrap:wrap;align-items:center}
  .disc{max-width:560px}

  @media(max-width:960px){
    .about-grid{grid-template-columns:1fr;gap:28px}
    .grid{grid-template-columns:repeat(2,1fr)}
    .nav nav a:not(.cart){display:none}
  }
  @media(max-width:560px){ .grid{grid-template-columns:1fr} .specs{gap:22px} }
</style>
</head>
<body>

<header class="nav">
  <div class="wrap">
    <div class="brand"><span class="mark">W</span><b>WastedToken&nbsp;<span>Mint</span></b></div>
    <nav>
      <a href="#about">The Mint</a>
      <a href="#collection">Collection</a>
      <a href="#about">Provenance</a>
      <a class="cart" href="#collection">Cart&nbsp;·&nbsp;<b id="cartCount">0</b></a>
    </nav>
  </div>
</header>

<main>
  <!-- HERO -->
  <section class="hero">
    <div class="wrap">
      <div class="eyebrow">Struck in the Troll Kingdom · Est. 2021</div>
      <h1>The WastedToken<br>Challenge Coin</h1>
      <p class="sub">A hand-numbered, solid-struck collectible. Reeded edge, raised relief,
        and a mirror-bright rake that walks the metal as it turns.</p>

      <div class="coin-stage">
        <canvas id="coin-hero" width="600" height="600"></canvas>
      </div>

      <div class="coin-cta">
        <button class="btn primary" data-add="Signature Mint · 10,000" data-price="149">Add signature coin — $149</button>
        <a class="btn ghost" href="#collection">View editions</a>
      </div>

      <div class="specs">
        <div><b>44&nbsp;mm</b>diameter</div>
        <div><b>3.2&nbsp;mm</b>reeded edge</div>
        <div><b>1.9&nbsp;oz</b>struck weight</div>
        <div><b>2,500</b>per edition</div>
      </div>
    </div>
  </section>

  <!-- ABOUT -->
  <section class="block" id="about">
    <div class="wrap about-grid">
      <div class="about">
        <div class="kicker">About the Mint</div>
        <h2 class="title">We turn wasted tokens into things worth keeping.</h2>
        <p>WastedToken Mint strikes physical challenge coins the old way — one die, one blank, one
          honest thunk of the press. Every coin carries the mint's raised emblem on the obverse and
          a denominated token count on the reverse, so the thing that lived only as a number finally
          has a weight in your hand.</p>
        <p>Each edition is capped, hand-numbered on the edge, and sealed with a capsule and a
          certificate of authenticity. No re-strikes, no secondary runs. When a season sells out,
          the die is retired for good — which is exactly why collectors keep the boxes.</p>
        <div class="pill-row">
          <span class="pill"><b>Solid</b>&nbsp;struck alloy</span>
          <span class="pill"><b>Reeded</b>&nbsp;numbered edge</span>
          <span class="pill"><b>Capsule</b>&nbsp;+ COA</span>
          <span class="pill"><b>Capped</b>&nbsp;mintages</span>
        </div>
      </div>
      <aside>
        <h3>Mint ledger</h3>
        <p style="color:var(--muted);margin:.2em 0 0">Current season figures, updated at strike.</p>
        <ul>
          <li>Coins struck to date <span>318,400</span></li>
          <li>Editions retired <span>11</span></li>
          <li>Avg. secondary premium <span>+62%</span></li>
          <li>Longest sell-out <span>4m 12s</span></li>
        </ul>
      </aside>
    </div>
  </section>

  <!-- COLLECTION -->
  <section class="block" id="collection">
    <div class="wrap">
      <div class="kicker">The Collection</div>
      <h2 class="title">Four metals. Four mintages.</h2>
      <p style="color:var(--muted);max-width:640px;margin-top:-6px">
        Every edition is struck from the same master relief, then finished in its own alloy.
        Same coin, four temperaments.</p>

      <div class="grid" id="editionGrid" style="margin-top:34px">

        <!-- BRONZE -->
        <div class="edition" data-edition="bronze" data-state="available">
          <div class="canvas-holder"><canvas class="edition-canvas" width="440" height="440"></canvas></div>
          <div class="row"><h3>Bronze</h3><span class="denom">1,000 TOKENS</span></div>
          <p class="desc">The first strike. Warm, antique patina with a deep reeded edge — the everyday carry of the collection.</p>
          <div class="foot">
            <span class="price">$49</span>
            <button class="buy" data-add="Bronze · 1,000" data-price="49">Add to cart</button>
          </div>
        </div>

        <!-- SILVER -->
        <div class="edition" data-edition="silver" data-state="available">
          <div class="canvas-holder"><canvas class="edition-canvas" width="440" height="440"></canvas></div>
          <div class="row"><h3>Silver</h3><span class="denom">5,000 TOKENS</span></div>
          <p class="desc">Bright proof finish with mirror fields and frosted relief. The collector's default and the fastest to move.</p>
          <div class="foot">
            <span class="price">$89</span>
            <button class="buy" data-add="Silver · 5,000" data-price="89">Add to cart</button>
          </div>
        </div>

        <!-- GOLD — SOLD OUT -->
        <div class="edition" data-edition="gold" data-state="sold-out">
          <div class="badge">SOLD OUT</div>
          <div class="canvas-holder"><canvas class="edition-canvas" width="440" height="440"></canvas></div>
          <div class="row"><h3>Gold</h3><span class="denom">10,000 TOKENS</span></div>
          <p class="desc">The flagship strike in deep antique gold. Capped at 2,500 and fully claimed — this edition is SOLD OUT and the die is retired.</p>
          <div class="foot">
            <span class="price">$149</span>
            <span class="status soldout">Sold Out</span>
          </div>
        </div>

        <!-- BLACK — COMING SOON -->
        <div class="edition" data-edition="black" data-state="coming-soon">
          <div class="badge dark">SEASON 12</div>
          <div class="canvas-holder"><canvas class="edition-canvas" width="440" height="440"></canvas></div>
          <div class="row"><h3>Obsidian</h3><span class="denom">25,000 TOKENS</span></div>
          <p class="desc">Black-ruthenium relief on a smoked mirror field. Minting next season — arriving Winter 2026. Not yet purchasable.</p>
          <div class="foot">
            <span class="price">TBA</span>
            <span class="status soon">Minting Next Season · Winter</span>
          </div>
        </div>

      </div>
    </div>
  </section>
</main>

<footer>
  <div class="wrap foot-grid">
    <div class="disc">
      <div class="brand" style="margin-bottom:10px"><span class="mark">W</span><b>WastedToken&nbsp;<span>Mint</span></b></div>
      <div>Collectible novelty coins. No monetary value, no redemption, purely legal tender of the Troll Kingdom.
        Mintages are capped and hand-numbered.</div>
    </div>
    <div>© 2026 WastedToken Mint · Struck to order · <span style="color:var(--gold)">bghurt@gmail.com</span></div>
  </div>
</footer>

<script>
"use strict";
(function(){
  const DPR = Math.min(window.devicePixelRatio || 1, 2);

  /* ---------------- color utils ---------------- */
  function hexToRgb(h){h=h.replace('#','');return[parseInt(h.slice(0,2),16),parseInt(h.slice(2,4),16),parseInt(h.slice(4,6),16)];}
  function scale(rgb,f){return`rgb(${Math.min(255,Math.max(0,rgb[0]*f))|0},${Math.min(255,Math.max(0,rgb[1]*f))|0},${Math.min(255,Math.max(0,rgb[2]*f))|0})`;}
  function norm(v){const m=Math.hypot(v.x,v.y,v.z)||1;return{x:v.x/m,y:v.y/m,z:v.z/m};}
  function dot(a,b){return a.x*b.x+a.y*b.y+a.z*b.z;}
  const clamp=(x,a,b)=>x<a?a:x>b?b:x;

  /* ---------------- palettes ---------------- */
  const P = {
    gold:  {light:'#ffe89a',mid:'#d4a52a',dark:'#8a6410',edge:'#5f450c',txtHi:'#fff3c0',txtSh:'#4a3606',txtBase:'#caa03a'},
    bronze:{light:'#f0b878',mid:'#b06a2e',dark:'#6e3f16',edge:'#4a2c10',txtHi:'#ffd7a0',txtSh:'#331d08',txtBase:'#a8672c'},
    silver:{light:'#ffffff',mid:'#c2c7cf',dark:'#7c828c',edge:'#565b64',txtHi:'#ffffff',txtSh:'#454951',txtBase:'#b0b5be'},
    black: {light:'#565a66',mid:'#242730',dark:'#12141a',edge:'#090a0e',txtHi:'#9aa0ad',txtSh:'#060709',txtBase:'#3d4049'}
  };

  /* ---------------- texture builder ---------------- */
  const S = 520, C = S/2, R = S/2*0.985;

  function metalBase(g, pal){
    const lg = g.createRadialGradient(S*0.40,S*0.36,20, C,C, R*1.06);
    lg.addColorStop(0, pal.light);
    lg.addColorStop(0.42, pal.mid);
    lg.addColorStop(0.80, pal.dark);
    lg.addColorStop(1, pal.edge);
    g.save();
    g.beginPath();g.arc(C,C,R,0,Math.PI*2);g.clip();
    g.fillStyle=lg;g.fillRect(0,0,S,S);
    // spun/brushed metal
    g.globalCompositeOperation='overlay';
    for(let i=0;i<520;i++){
      const a=i/520*Math.PI*2;
      const b=(Math.sin(i*12.9898)*0.5+0.5);
      g.strokeStyle=`rgba(255,255,255,${0.015+0.02*b})`;
      g.beginPath();g.moveTo(C,C);
      g.lineTo(C+Math.cos(a)*R,C+Math.sin(a)*R);g.lineWidth=1;g.stroke();
    }
    // turned rings
    g.globalCompositeOperation='soft-light';
    for(let r=24;r<R;r+=6){
      g.strokeStyle=(r%12<6)?'rgba(255,255,255,.05)':'rgba(0,0,0,.06)';
      g.beginPath();g.arc(C,C,r,0,Math.PI*2);g.stroke();
    }
    g.restore();
    g.globalCompositeOperation='source-over';
  }

  function embossChar(g,ch,hi,sh,base,off){
    g.fillStyle=sh; g.fillText(ch,off,off);
    g.fillStyle=hi; g.fillText(ch,-off,-off);
    g.fillStyle=base; g.fillText(ch,0,0);
  }
  function embossPath(g,pathFn,hi,sh,base,off){
    g.save();g.translate(off,off);g.fillStyle=sh;pathFn();g.fill();g.restore();
    g.save();g.translate(-off,-off);g.fillStyle=hi;pathFn();g.fill();g.restore();
    g.fillStyle=base;pathFn();g.fill();
  }
  function arcText(g,text,radius,mid,size,flip,cols){
    g.save();
    g.font=`700 ${size}px ${'"Palatino Linotype",Palatino,Georgia,serif'}`;
    g.textAlign='center';g.textBaseline='middle';
    const chars=[...text];
    const widths=chars.map(c=>g.measureText(c).width+size*0.06);
    const total=widths.reduce((a,b)=>a+b,0);
    const span=total/radius;
    let a=mid-span/2*(flip?-1:1);
    for(let i=0;i<chars.length;i++){
      const w=widths[i];
      const ca=a+(w/2)/radius*(flip?-1:1);
      const x=C+Math.cos(ca)*radius, y=C+Math.sin(ca)*radius;
      g.save();g.translate(x,y);
      g.rotate(ca+Math.PI/2+(flip?Math.PI:0));
      embossChar(g,chars[i],cols.hi,cols.sh,cols.base,1.3);
      g.restore();
      a+=(w/radius)*(flip?-1:1);
    }
    g.restore();
  }
  function beads(g,radius,n,cols){
    for(let i=0;i<n;i++){
      const a=i/n*Math.PI*2, x=C+Math.cos(a)*radius, y=C+Math.sin(a)*radius;
      g.beginPath();g.arc(x+1,y+1,2.6,0,Math.PI*2);g.fillStyle=cols.sh;g.fill();
      g.beginPath();g.arc(x-0.6,y-0.6,2.2,0,Math.PI*2);g.fillStyle=cols.hi;g.fill();
      g.beginPath();g.arc(x,y,1.7,0,Math.PI*2);g.fillStyle=cols.base;g.fill();
    }
  }
  function guilloche(g,baseR,amp,petals,phase,col){
    g.beginPath();
    for(let i=0;i<=360;i++){
      const a=i*Math.PI/180, r=baseR+amp*Math.sin(petals*a+phase);
      const x=C+Math.cos(a)*r, y=C+Math.sin(a)*r;
      i?g.lineTo(x,y):g.moveTo(x,y);
    }
    g.closePath();g.strokeStyle=col;g.lineWidth=1;g.stroke();
  }
  function rimRing(g,pal,cols){
    // raised outer ring
    g.save();
    g.lineWidth=14;
    g.strokeStyle=scale(hexToRgb(pal.dark),0.7);g.beginPath();g.arc(C+1.5,C+1.5,R-16,0,Math.PI*2);g.stroke();
    g.strokeStyle=scale(hexToRgb(pal.light),1.0);g.beginPath();g.arc(C-1.5,C-1.5,R-16,0,Math.PI*2);g.stroke();
    g.strokeStyle=pal.mid;g.beginPath();g.arc(C,C,R-16,0,Math.PI*2);g.stroke();
    g.restore();
  }

  function buildFront(pal){
    const cv=document.createElement('canvas');cv.width=S;cv.height=S;
    const g=cv.getContext('2d');
    metalBase(g,pal);
    const cols={hi:pal.txtHi,sh:pal.txtSh,base:pal.txtBase};
    // guilloche field
    g.save();g.globalAlpha=0.5;
    guilloche(g,158,10,26,0, scale(hexToRgb(pal.light),1.05));
    guilloche(g,152,8,26,0.4, scale(hexToRgb(pal.dark),0.9));
    guilloche(g,140,6,34,1.1, scale(hexToRgb(pal.light),1.0));
    g.restore();
    rimRing(g,pal,cols);
    beads(g,R-34,120,cols);
    // ring text
    arcText(g,'WASTEDTOKEN  MINT',R-58,-Math.PI/2,30,false,cols);
    arcText(g,'COLLECTIBLE  CHALLENGE  COIN',R-58,Math.PI/2,20,true,cols);
    // side stars
    [0,Math.PI].forEach(a=>{
      g.save();g.translate(C+Math.cos(a)*(R-58),C+Math.sin(a)*(R-58));
      g.font='700 22px Georgia,serif';g.textAlign='center';g.textBaseline='middle';
      embossChar(g,'✦',cols.hi,cols.sh,cols.base,1.2);g.restore();
    });
    // central hexagon medallion (raised)
    const hex=()=>{g.beginPath();for(let i=0;i<6;i++){const a=-Math.PI/2+i*Math.PI/3;const x=C+Math.cos(a)*96,y=C+Math.sin(a)*96;i?g.lineTo(x,y):g.moveTo(x,y);}g.closePath();};
    embossPath(g,hex,scale(hexToRgb(pal.light),1.06),scale(hexToRgb(pal.dark),0.72),pal.mid,2.4);
    // inner hex outline
    g.lineWidth=3;g.strokeStyle=scale(hexToRgb(pal.dark),0.85);g.beginPath();
    for(let i=0;i<6;i++){const a=-Math.PI/2+i*Math.PI/3;const x=C+Math.cos(a)*78,y=C+Math.sin(a)*78;i?g.lineTo(x,y):g.moveTo(x,y);}g.closePath();g.stroke();
    // monogram
    g.textAlign='center';g.textBaseline='middle';
    g.font='900 88px Georgia,"Times New Roman",serif';
    embossChar.call(null,g,'W',cols.hi,cols.sh,cols.base,2.2); // placeholder overwritten below
    // draw WT combined
    g.font='900 82px Georgia,serif';
    g.save();g.translate(C,C+6);
    embossChar(g,'WT',cols.hi,cols.sh,cols.base,2.2);
    g.restore();
    // small star above
    g.font='700 20px Georgia,serif';g.save();g.translate(C,C-60);
    embossChar(g,'★',cols.hi,cols.sh,cols.base,1.2);g.restore();
    // est line
    g.font='700 15px Georgia,serif';g.save();g.translate(C,C+70);
    embossChar(g,'EST · 2021',cols.hi,cols.sh,cols.base,1);g.restore();
    return cv;
  }

  function buildBack(pal,denom){
    const cv=document.createElement('canvas');cv.width=S;cv.height=S;
    const g=cv.getContext('2d');
    metalBase(g,pal);
    const cols={hi:pal.txtHi,sh:pal.txtSh,base:pal.txtBase};
    g.save();g.globalAlpha=0.45;
    guilloche(g,150,9,40,0, scale(hexToRgb(pal.light),1.05));
    guilloche(g,150,9,40,Math.PI/40, scale(hexToRgb(pal.dark),0.9));
    g.restore();
    rimRing(g,pal,cols);
    beads(g,R-34,120,cols);
    arcText(g,'WASTEDTOKEN  MINT',R-58,-Math.PI/2,30,false,cols);
    arcText(g,'· LEGAL TENDER OF THE TROLL KINGDOM ·',R-58,Math.PI/2,17,true,cols);
    // star above number
    g.textAlign='center';g.textBaseline='middle';
    g.font='700 30px Georgia,serif';g.save();g.translate(C,C-92);
    embossChar(g,'✦',cols.hi,cols.sh,cols.base,1.4);g.restore();
    // laurel dots ring around number
    g.save();g.globalAlpha=0.85;
    for(let i=0;i<44;i++){const a=i/44*Math.PI*2;const x=C+Math.cos(a)*130,y=C+Math.sin(a)*130;
      g.beginPath();g.arc(x,y,1.6,0,Math.PI*2);g.fillStyle=(i%2?cols.hi:cols.sh);g.fill();}
    g.restore();
    // big denomination
    g.font='900 92px Georgia,"Times New Roman",serif';g.save();g.translate(C,C-14);
    embossChar(g,denom,cols.hi,cols.sh,cols.base,2.6);g.restore();
    // TOKENS
    g.font='700 34px Georgia,serif';g.save();g.translate(C,C+56);
    g.letterSpacing='6px';
    embossChar(g,'TOKENS',cols.hi,cols.sh,cols.base,1.8);g.restore();
    return cv;
  }

  /* ---------------- Coin renderer ---------------- */
  const Ldir = norm({x:-0.40,y:-0.55,z:0.72});         // canvas y is down => light from upper-left
  const Vdir = {x:0,y:0,z:1};
  const Hvec = norm({x:Ldir.x+Vdir.x, y:Ldir.y+Vdir.y, z:Ldir.z+Vdir.z});

  class CoinRenderer{
    constructor(canvas, cfg){
      this.canvas=canvas; this.ctx=canvas.getContext('2d');
      this.pal=cfg.pal; this.palRGB={edge:hexToRgb(cfg.pal.edge),mid:hexToRgb(cfg.pal.mid),light:hexToRgb(cfg.pal.light),dark:hexToRgb(cfg.pal.dark)};
      this.front=buildFront(cfg.pal);
      this.back=buildBack(cfg.pal,cfg.denom);
      this.tilt0=cfg.tilt0!==undefined?cfg.tilt0:-0.22;
      this.amp=cfg.amp!==undefined?cfg.amp:0.55;
      this.staticT=cfg.staticT;
      this.hero=!!cfg.hero;
      this.resize();
    }
    resize(){
      const r=this.canvas.getBoundingClientRect();
      const cssW=r.width||this.canvas.width, cssH=r.height||this.canvas.height;
      this.canvas.width=Math.round(cssW*DPR);
      this.canvas.height=Math.round(cssH*DPR);
      this.W=this.canvas.width;this.H=this.canvas.height;
      this.cx=this.W/2;this.cy=this.H/2;
      this.Rr=Math.min(this.W,this.H)*0.335;
      this.h=this.Rr*0.10;
    }
    drawBackdrop(){
      const g=this.ctx, {W,H}=this;
      const bg=g.createRadialGradient(W*0.5,H*0.42,10,W*0.5,H*0.55,Math.max(W,H)*0.72);
      bg.addColorStop(0, this.hero?'#20222c':'#191b22');
      bg.addColorStop(0.55, this.hero?'#101119':'#0f1017');
      bg.addColorStop(1, '#08090d');
      g.fillStyle=bg;g.fillRect(0,0,W,H);
    }
    render(t){
      const g=this.ctx, {W,H,cx,cy,Rr,h}=this;
      const pal=this.pal, pr=this.palRGB;
      g.setTransform(1,0,0,1,0,0);
      g.clearRect(0,0,W,H);
      this.drawBackdrop();

      const a=2*Math.PI*t;
      const b=this.tilt0+this.amp*Math.sin(2*Math.PI*t);
      const ca=Math.cos(a),sa=Math.sin(a),cb=Math.cos(b),sb=Math.sin(b);
      const u={x:ca, y:sa*sb, z:-sa*cb};
      const v={x:0,  y:cb,    z:sb};
      const w={x:sa, y:-ca*sb,z:ca*cb};

      const proj=(lx,ly,lz)=>({x:cx+u.x*lx+v.x*ly+w.x*lz, y:cy-(u.y*lx+v.y*ly+w.y*lz), z:u.z*lx+v.z*ly+w.z*lz});
      const N=110;
      const pathRim=(lz)=>{g.beginPath();for(let i=0;i<=N;i++){const ph=i/N*Math.PI*2,p=proj(Math.cos(ph)*Rr,Math.sin(ph)*Rr,lz);i?g.lineTo(p.x,p.y):g.moveTo(p.x,p.y);}g.closePath();};

      const nearFront = w.z>0;
      const Nf = nearFront? w : {x:-w.x,y:-w.y,z:-w.z};
      const lzNear = nearFront? h/2 : -h/2;
      const lzFar  = -lzNear;

      // 1) far face (dim fill so silhouette is solid behind edge)
      pathRim(lzFar);
      g.fillStyle=scale(pr.edge,0.9);g.fill();

      // 2) reeded edge — painter-sorted quads
      const quads=[];
      const REED=90;
      for(let i=0;i<N;i++){
        const p0=i/N*Math.PI*2, p1=(i+1)/N*Math.PI*2, pm=(p0+p1)/2;
        const A=proj(Math.cos(p0)*Rr,Math.sin(p0)*Rr, h/2);
        const B=proj(Math.cos(p1)*Rr,Math.sin(p1)*Rr, h/2);
        const D=proj(Math.cos(p1)*Rr,Math.sin(p1)*Rr,-h/2);
        const E=proj(Math.cos(p0)*Rr,Math.sin(p0)*Rr,-h/2);
        const nq={x:u.x*Math.cos(pm)+v.x*Math.sin(pm), y:u.y*Math.cos(pm)+v.y*Math.sin(pm), z:u.z*Math.cos(pm)+v.z*Math.sin(pm)};
        const diff=clamp(dot(nq,Ldir),0,1);
        const spec=Math.pow(clamp(dot(nq,Hvec),0,1),8);
        const reed=0.5+0.5*Math.sin(pm*REED);
        const bright=(0.30+0.70*diff)*(0.60+0.40*reed)+0.55*spec;
        quads.push({pts:[A,B,D,E], z:(A.z+B.z+D.z+E.z)/4, col:scale(pr.edge, 0.55+bright*0.9)});
      }
      quads.sort((x,y)=>x.z-y.z);
      for(const q of quads){
        g.beginPath();g.moveTo(q.pts[0].x,q.pts[0].y);
        for(let k=1;k<4;k++)g.lineTo(q.pts[k].x,q.pts[k].y);
        g.closePath();g.fillStyle=q.col;g.fill();
      }

      // 3) near face — texture mapped onto ellipse
      const tex = nearFront? this.front : this.back;
      const mirror = !nearFront;
      const kS = Rr/(S/2), sx = mirror?-1:1;
      const fc = proj(0,0,lzNear);
      g.save();
      g.setTransform(u.x*kS*sx, -u.y*kS*sx, v.x*kS, -v.y*kS, fc.x, fc.y);
      g.drawImage(tex, -S/2, -S/2);
      g.restore();
      g.setTransform(1,0,0,1,0,0);

      // 3b) dynamic shading + raking specular, clipped to the face
      g.save();
      pathRim(lzNear); g.clip();

      // diffuse shadow on the dark side of the face
      const NfL=clamp(dot(Nf,Ldir),0,1);
      g.fillStyle=`rgba(6,6,10,${(1-NfL)*0.5})`;
      g.fillRect(0,0,W,H);

      // specular hotspot position (in the face plane, from half-vector)
      let hu=dot(Hvec,u), hv=dot(Hvec,v);
      const mag=Math.hypot(hu,hv);
      let hx=0,hy=0;
      if(mag>1e-4){const rad=Math.min(mag*1.15,0.82)*Rr; hx=hu/mag*rad; hy=hv/mag*rad;}
      const sp=proj(hx,hy,lzNear);
      const NfH=clamp(dot(Nf,Hvec),0,1);
      const specA=0.92*(0.25+0.75*Math.pow(NfH,2.4));
      g.globalCompositeOperation='lighter';
      const gr=g.createRadialGradient(sp.x,sp.y,0, sp.x,sp.y, Rr*0.62);
      gr.addColorStop(0,`rgba(255,252,240,${specA})`);
      gr.addColorStop(0.35,`rgba(255,245,220,${specA*0.45})`);
      gr.addColorStop(1,'rgba(255,245,220,0)');
      g.fillStyle=gr;g.fillRect(0,0,W,H);
      // secondary broad sheen for metallic depth
      const gr2=g.createRadialGradient(sp.x,sp.y,0, sp.x,sp.y, Rr*1.1);
      gr2.addColorStop(0,`rgba(255,255,255,${specA*0.18})`);
      gr2.addColorStop(1,'rgba(255,255,255,0)');
      g.fillStyle=gr2;g.fillRect(0,0,W,H);
      g.globalCompositeOperation='source-over';
      g.restore();

      // crisp rim line
      pathRim(lzNear);
      g.lineWidth=Math.max(1,Rr*0.012);
      g.strokeStyle=scale(pr.dark,0.7);g.stroke();
    }
  }

  /* ---------------- boot ---------------- */
  const heroCanvas=document.getElementById('coin-hero');
  const hero=new CoinRenderer(heroCanvas,{pal:P.gold,denom:'10,000',hero:true,tilt0:-0.24,amp:0.60});

  // editions
  const edCfg={
    bronze:{pal:P.bronze,denom:'1,000',staticT:0.06},
    silver:{pal:P.silver,denom:'5,000',staticT:0.94},
    gold:  {pal:P.gold,  denom:'10,000',staticT:0.09},
    black: {pal:P.black, denom:'25,000',staticT:0.91}
  };
  const edRenderers=[];
  document.querySelectorAll('.edition').forEach(tile=>{
    const key=tile.getAttribute('data-edition');
    const cv=tile.querySelector('.edition-canvas');
