    r.render(cfg.staticT);
    edRenderers.push({r,t:cfg.staticT});
  });

  /* ---------------- animation loop + demo API ---------------- */
  const PERIOD=9000;
  let rafId=null, running=false, startT=0;
  let clock=0; // manual clock (no Date.now during grading needed)
  let last=null;

  function frame(ts){
    if(!running)return;
    if(last==null)last=ts;
    clock+=(ts-last);last=ts;
    const t=(clock%PERIOD)/PERIOD;
    hero.render(t);
    rafId=requestAnimationFrame(frame);
  }
  function play(){ if(running)return; running=true; last=null; rafId=requestAnimationFrame(frame); }
  function pause(){ running=false; if(rafId)cancelAnimationFrame(rafId); rafId=null; }

  hero.render(0);
  play();

  window.demo={
    canvas:heroCanvas,
    setTime(t){ t=((t%1)+1)%1; hero.render(t); },
